pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());
        vm.assume(newOwner != address(0));
        assertTrue(_tryTransferOwner(caller, newOwner));
    }
    function _tryTransferOwner(address caller, address newOwner) internal returns (bool) {
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            return false;
        } catch {
            return true;
        }
    }
}
